def _sp(files):
    return [f.short_path for f in files]

def _rf(r):
    return {
        "files": _sp(r.files.to_list()),
        "symlinks": [[s.path, s.target_file.short_path] for s in r.symlinks.to_list()],
        "root_symlinks": [[s.path, s.target_file.short_path] for s in r.root_symlinks.to_list()],
        "empty": r.empty_filenames.to_list(),
    }

def _p(fn):
    return fn.path if fn else None

def _s(fn):
    return fn.short_path if fn else None

def _show(ctx):
    m = ctx.attr.mode
    a, b, c = ctx.file.a, ctx.file.b, ctx.file.c
    R = ctx.runfiles
    v = None
    ret = []
    if m == "files_order":
        v = _rf(R(files = [b], transitive_files = depset([a])))
    elif m == "files_dups":
        v = _rf(R(files = [a, b, a]))
    elif m == "files_tuple":
        v = _rf(R(files = (a,)))
    elif m == "files_none":
        v = _rf(R(files = None))
    elif m == "positional":
        v = _rf(R([a], depset([b])))
    elif m == "positional_all":
        v = _rf(R([a], depset([b]), False, False, {"s": c}, {"r": c}))
    elif m == "transitive_default":
        v = _rf(R(transitive_files = depset([a, b], order = "default")))
    elif m == "transitive_postorder_nested":
        v = _rf(R(transitive_files = depset([a], transitive = [depset([b])], order = "postorder")))
    elif m == "transitive_nested_default_in_postorder":
        v = _rf(R(transitive_files = depset([c], transitive = [depset([a, b])], order = "postorder")))
    elif m == "transitive_preorder_empty":
        v = _rf(R(transitive_files = depset(order = "preorder")))
    elif m == "transitive_topological_empty":
        v = _rf(R(transitive_files = depset(order = "topological")))
    elif m == "transitive_preorder":
        v = _rf(R(transitive_files = depset([a], order = "preorder")))
    elif m == "transitive_none":
        v = _rf(R(transitive_files = None))
    elif m == "symlinks_normalize":
        v = _rf(R(symlinks = {"x/./y//z": a, "q/../w": b, "trail/": c}))
    elif m == "symlinks_up":
        v = _rf(R(symlinks = {"../up": a}))
    elif m == "symlinks_up_inner":
        v = _rf(R(symlinks = {"a/../../up": a}))
    elif m == "symlinks_abs":
        v = _rf(R(symlinks = {"/abs/p": a}))
    elif m == "symlinks_empty_key":
        v = _rf(R(symlinks = {"": a}))
    elif m == "symlinks_dot":
        v = _rf(R(symlinks = {".": a}))
    elif m == "symlinks_order":
        v = _rf(R(symlinks = {"z": a, "a": b, "m": c}, root_symlinks = {"z": a, "a": b}))
    elif m == "symlinks_depset_empty":
        v = _rf(R(symlinks = depset(), root_symlinks = depset()))
    elif m == "symlinks_depset_copy":
        s = R(symlinks = {"k": a})
        v = _rf(R(symlinks = s.symlinks, root_symlinks = s.symlinks))
    elif m == "symlinks_none":
        v = _rf(R(symlinks = None))
    elif m == "symlinks_key_int":
        v = _rf(R(symlinks = {1: a}))
    elif m == "root_symlinks_normalize":
        v = _rf(R(root_symlinks = {"a/./b": a, "c//d/": b}))
    elif m == "root_symlinks_value_string":
        v = _rf(R(root_symlinks = {"k": "v"}))
    elif m == "symlink_entry":
        e = R(symlinks = {"k": a}).symlinks.to_list()[0]
        v = [type(e), dir(e), e.path, e.target_file.short_path]
    elif m == "symlink_entry_repr":
        v = repr(R(symlinks = {"k": a}).symlinks.to_list()[0])
    elif m == "symlink_entry_identity":
        r = R(symlinks = {"k": a})
        v = [r.symlinks.to_list()[0] == r.symlinks.to_list()[0], R(symlinks = {"k": a}).symlinks.to_list()[0] == R(symlinks = {"k": a}).symlinks.to_list()[0]]
    elif m == "symlink_entry_nofield":
        v = R(symlinks = {"k": a}).symlinks.to_list()[0].nope
    elif m == "runfiles_surface":
        r = R(files = [a])
        v = [type(r), repr(r), str(r), dir(r), type(r.files), type(r.symlinks), type(r.root_symlinks), type(r.empty_filenames)]
    elif m == "runfiles_depset_reprs":
        e = R()
        v = [str(e.files), str(e.symlinks), str(e.root_symlinks), str(e.empty_filenames)]
    elif m == "runfiles_nofield":
        v = R().nope
    elif m == "runfiles_hash":
        v = len({R(): 1})
    elif m == "runfiles_bool":
        v = [bool(R()), bool(R(files = [a]))]
    elif m == "runfiles_setfield":
        r = R()
        r.files = depset()
    elif m == "merge_order":
        r1 = R(files = [a])
        r2 = R(files = [b])
        r3 = R(files = [c])
        v = [_sp(r1.merge(r2).files.to_list()), _sp(r1.merge_all([r2, r3]).files.to_list()), _sp(r3.merge_all([r1, r2]).files.to_list()), _sp(r1.merge(r2).merge(r3).files.to_list()), _sp(R(files = [b], transitive_files = depset([c])).merge(R(files = [a])).files.to_list())]
    elif m == "merge_identity_extra":
        r = R(files = [a])
        e = R()
        v = [r.merge(r) == r, r.merge_all([r]) == r, e.merge(e) == e, e.merge_all([e]) == e, r.merge_all([]) == r, r.merge_all([]) == e.merge_all([]), R(files = []) == R(), R(symlinks = {}) == R(), e.merge(R()) == e, R().merge(e) == e, r.merge_all([e, e]) == r]
    elif m == "merge_symlink_dups":
        v = _rf(R(symlinks = {"s": a}).merge(R(symlinks = {"s": b})))
    elif m == "merge_same_symlink":
        v = _rf(R(symlinks = {"s": a}).merge(R(symlinks = {"s": a})))
    elif m == "merge_none":
        v = R().merge(None)
    elif m == "merge_kw":
        v = _rf(R(files = [a]).merge(other = R(files = [b])))
    elif m == "merge_all_tuple":
        v = _rf(R(files = [a]).merge_all((R(files = [b]),)))
    elif m == "merge_all_depset":
        v = R().merge_all(depset())
    elif m == "merge_all_none":
        v = R().merge_all(None)
    elif m == "collect_both":
        v = _rf(R(collect_data = True, collect_default = True))
    elif m == "collect_data_with_files":
        v = _rf(R(files = [c], collect_data = True))
    elif m == "collect_default_srcs_files":
        v = _rf(R(collect_default = True))
    elif m == "collect_data_flag":
        v = _rf(R(collect_data = True))
    elif m == "collect_none_kw":
        v = _rf(R(collect_data = None))
    elif m == "skip_false":
        v = _rf(R(skip_conflict_checking = False))
    elif m == "di_empty":
        d = DefaultInfo()
        v = [d.files, d.files_to_run, d.data_runfiles, d.default_runfiles, dir(d), type(d), repr(d), str(d)]
    elif m == "di_files":
        d = DefaultInfo(files = depset([a]))
        v = [_sp(d.files.to_list()), d.files_to_run, d.data_runfiles, d.default_runfiles]
    elif m == "di_executable":
        d = DefaultInfo(executable = a)
        v = [d.files, d.files_to_run, d.data_runfiles, d.default_runfiles]
    elif m == "di_runfiles":
        r = R(files = [a])
        d = DefaultInfo(runfiles = r)
        v = [d.default_runfiles == r, d.data_runfiles == r, d.data_runfiles == d.default_runfiles, d.data_runfiles]
    elif m == "di_stateful":
        r1 = R(files = [a])
        r2 = R(files = [b])
        d = DefaultInfo(data_runfiles = r1, default_runfiles = r2)
        v = [d.data_runfiles == r1, d.default_runfiles == r2]
    elif m == "di_runfiles_with_none":
        d = DefaultInfo(runfiles = R(files = [a]), data_runfiles = None, default_runfiles = None)
        v = [_rf(d.default_runfiles), _rf(d.data_runfiles)]
    elif m == "di_runfiles_with_default":
        v = DefaultInfo(runfiles = R(), default_runfiles = R())
    elif m == "di_files_list":
        v = DefaultInfo(files = [a])
    elif m == "di_files_depset_strings_unreturned":
        d = DefaultInfo(files = depset(["x"]))
        v = type(d.files)
    elif m == "di_executable_string":
        v = DefaultInfo(executable = "x")
    elif m == "di_runfiles_int":
        v = DefaultInfo(runfiles = 1)
    elif m == "di_data_runfiles_depset":
        v = DefaultInfo(data_runfiles = depset([a]))
    elif m == "di_positional":
        v = DefaultInfo(depset([a]))
    elif m == "di_unknown_kw":
        v = DefaultInfo(foo = 1)
    elif m == "di_nofield":
        v = DefaultInfo().nope
    elif m == "di_eq":
        v = [DefaultInfo() == DefaultInfo(), DefaultInfo(files = depset([a])) == DefaultInfo(files = depset([a]))]
    elif m == "di_provider":
        v = [type(DefaultInfo), str(DefaultInfo), repr(DefaultInfo)]
    elif m == "di_return_two":
        ret = [DefaultInfo(), DefaultInfo()]
    elif m == "di_return_files_none":
        ret = [DefaultInfo(files = None)]
    elif m == "di_return_runfiles_only":
        ret = [DefaultInfo(runfiles = R(files = [a]))]
    elif m == "di_return_struct":
        ret = struct(runfiles = R())
    elif m == "di_return_executable_source":
        ret = [DefaultInfo(executable = a)]
    elif m == "di_return_executable_owned":
        o = ctx.actions.declare_file(m + ".sh")
        ctx.actions.write(o, "#!/bin/sh\n", is_executable = True)
        ret = [DefaultInfo(executable = o)]
    elif m == "ctx_surface":
        v = [type(ctx.outputs), dir(ctx.outputs), hasattr(ctx, "runfiles"), hasattr(ctx, "executable"), type(ctx.executable), dir(ctx.executable)]
